        ...
    end;

    function closeLLMSession(session: LLMSession): Unit is
        -- Pontosan egyszer hívható, a compiler garantálja
        ...
    end;

    function runAgentLoop(
        session: LLMSession, 
        task: String, 
        iteration: Int32
    ): (LLMSession, String) is
        if iteration > 20 then
            return (session, "Max iterations reached");
        end if;

        let (session, response) := callLLM(session, buildPrompt(task));
        let toolCall := parseToolCall(response);

        case toolCall of
